      "type": "mingju",
      "unit": "mingju_jingshi",
      "seg": 1,
      "exam": 2,
      "module": "mingju",
      "t": "文章本天成，妙手偶得之。",
      "s": "文章本天成，妙手偶得之。",
      "author_t": "陸游",
      "author_s": "陆游",
      "src_t": "《文章》",
      "src_s": "《文章》",
