      "type": "mingju",
      "unit": "mingju_jingshi",
      "seg": 1,
      "exam": 2,
      "module": "mingju",
      "t": "出師一表真名世，千載誰堪伯仲間！",
      "s": "出师一表真名世，千载谁堪伯仲间！",
      "author_t": "陸游",
      "author_s": "陆游",
      "src_t": "《書憤》",
      "src_s": "《书愤》",
