      "type": "mingju",
      "unit": "mingju_jingshi",
      "seg": 1,
      "exam": 2,
      "module": "mingju",
      "t": "疏影橫斜水清淺，暗香浮動月黃昏。",
      "s": "疏影横斜水清浅，暗香浮动月黄昏。",
      "author_t": "林逋",
      "author_s": "林逋",
