      "seg": 1,
      "exam": 2,
      "module": "mingju",
      "t": "小荷才露尖尖角，早有蜻蜓立上頭。",
      "s": "小荷才露尖尖角，早有蜻蜓立上头。",
      "author_t": "楊萬里",
      "author_s": "杨万里",
