      "seg": 1,
      "exam": 2,
      "module": "mingju",
      "t": "畢竟西湖六月中，風光不與四時同。",
      "s": "毕竟西湖六月中，风光不与四时同。",
      "author_t": "楊萬里",
      "author_s": "杨万里",
